    86→	client := &PostHogClient{
    87→		machineID: "test-id",
    88→	}
    89→
    90→	completionCmd := &cobra.Command{
    91→		Use: "completion",
    92→	}
    93→
    94→	// Should not panic and should skip completion command
    95→	client.TrackCommand(completionCmd, "manual-commit", "claude-code", true)
    96→}
