    98→func TestPostHogClientSkipsNilCommand(_ *testing.T) {
    99→	client := &PostHogClient{
   100→		machineID: "test-id",
   101→	}
   102→
   103→	// Should not panic with nil command
   104→	client.TrackCommand(nil, "", "", false)
   105→}
