	client := &PostHogClient{
		machineID: "test-id",
	}

	helpCmd := &cobra.Command{
		Use: "help",
	}

	// Should not panic and should skip help command
	client.TrackCommand(helpCmd, "manual-commit", "claude-code", true)
}

