  1096→// countSessionStates returns the number of active session state files.
  1097→func countSessionStates() int {
  1098→	store, err := session.NewStateStore()
  1099→	if err != nil {
  1100→		return 0
  1101→	}
  1102→	states, err := store.List(context.Background())
  1103→	if err != nil {
  1104→		return 0
  1105→	}
  1106→	return len(states)
