   208→		}
   209→		settings.StrategyOptions["disable_multisession_warning"] = true
   210→	}
   211→
   212→	// Handle telemetry for non-interactive mode
   213→	// Note: if telemetry is nil (not configured), it defaults to disabled
   214→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   215→		f := false
   216→		settings.Telemetry = &f
   217→	}
   218→
   219→	// Determine which settings file to write to
   220→	entireDirAbs, err := paths.AbsPath(paths.EntireDir)
   221→	if err != nil {
   222→		entireDirAbs = paths.EntireDir // Fallback to relative
   223→	}
   224→	shouldUseLocal, showNotification := determineSettingsTarget(entireDirAbs, useLocalSettings, useProjectSettings)
   225→
   226→	if showNotification {
   227→		fmt.Fprintln(w, "Info: Project settings exist. Saving to settings.local.json instead.")
   228→		fmt.Fprintln(w, "  Use --project to update the project settings file.")
   229→	}
   230→
   231→	if shouldUseLocal {
   232→		if err := SaveEntireSettingsLocal(settings); err != nil {
   233→			return fmt.Errorf("failed to save local settings: %w", err)
   234→		}
   235→		fmt.Fprintln(w, "✓ Local settings saved (.entire/settings.local.json)")
   236→	} else {
   237→		if err := SaveEntireSettings(settings); err != nil {
   238→			return fmt.Errorf("failed to save settings: %w", err)
   239→		}
   240→		fmt.Fprintln(w, "✓ Project settings saved (.entire/settings.json)")
   241→	}
   242→
   243→	// Install git hooks (always reinstall to ensure they're up-to-date)
   244→	gitHooksInstalled, err := strategy.InstallGitHook(true)
   245→	if err != nil {
   246→		return fmt.Errorf("failed to install git hooks: %w", err)
   247→	}
   248→	if gitHooksInstalled > 0 {
   249→		fmt.Fprintln(w, "✓ Git hooks installed")
   250→	} else {
   251→		fmt.Fprintln(w, "✓ Git hooks verified")
   252→	}
   253→
   254→	// Let the strategy handle its own setup requirements
   255→	if err := strat.EnsureSetup(); err != nil {
   256→		return fmt.Errorf("failed to setup strategy: %w", err)
   257→	}
   258→
   259→	// Setup shell completion if --setup-shell flag was provided
   260→	if setupShell {
   261→		if err := setupShellCompletionNonInteractive(w); err != nil {
   262→			// Non-fatal - just log and continue
   263→			fmt.Fprintf(w, "Note: Shell completion setup skipped: %v\n", err)
   264→		}
   265→	}
   266→
   267→	// Show success message with display name
   268→	displayName := selectedStrategy
   269→	if dn, ok := strategyInternalToDisplay[internalStrategy]; ok {
   270→		displayName = dn
   271→	}
   272→	fmt.Fprintf(w, "\n✓ %s strategy enabled\n", displayName)
   273→
   274→	return nil
   275→}
