   569→// setupAgentHooksNonInteractive sets up hooks for a specific agent non-interactively.
   570→// If strategyName is provided, it sets the strategy; otherwise uses default.
   571→func setupAgentHooksNonInteractive(agentName agent.AgentName, strategyName string, localDev, forceHooks, skipPushSessions, telemetry, disableMultisessionWarning bool) error {
   572→	ag, err := agent.Get(agentName)
   573→	if err != nil {
   574→		return fmt.Errorf("unknown agent: %s", agentName)
   575→	}
   576→
   577→	// Check if agent supports hooks
   578→	hookAgent, ok := ag.(agent.HookSupport)
   579→	if !ok {
   580→		return fmt.Errorf("agent %s does not support hooks", agentName)
   581→	}
   582→
   583→	// Install hooks
   584→	count, err := hookAgent.InstallHooks(localDev, forceHooks)
   585→	if err != nil {
   586→		return fmt.Errorf("failed to install hooks for %s: %w", agentName, err)
   587→	}
   588→
   589→	if count == 0 {
   590→		msg := fmt.Sprintf("Hooks for %s already installed", ag.Description())
   591→		if agentName == agent.AgentNameGemini {
   592→			msg += " - This is a work in progress"
   593→		}
   594→		fmt.Println(msg)
   595→	} else {
   596→		msg := fmt.Sprintf("Installed %d hooks for %s", count, ag.Description())
   597→		if agentName == agent.AgentNameGemini {
   598→			msg += " - This is a work in progress"
   599→		}
   600→		fmt.Println(msg)
   601→	}
   602→
   603→	// Update settings to store the agent choice and strategy
   604→	settings, _ := LoadEntireSettings() //nolint:errcheck // settings defaults are fine
   605→	settings.Agent = string(agentName)
   606→	settings.Enabled = true
   607→	if localDev {
   608→		settings.LocalDev = localDev
   609→	}
   610→
   611→	// Set push_sessions option if --skip-push-sessions flag was provided
   612→	if skipPushSessions {
   613→		if settings.StrategyOptions == nil {
   614→			settings.StrategyOptions = make(map[string]interface{})
   615→		}
   616→		settings.StrategyOptions["push_sessions"] = false
   617→	}
   618→
   619→	// Set disable_multisession_warning option if --disable-multisession-warning flag was provided
   620→	if disableMultisessionWarning {
   621→		if settings.StrategyOptions == nil {
   622→			settings.StrategyOptions = make(map[string]interface{})
   623→		}
   624→		settings.StrategyOptions["disable_multisession_warning"] = true
   625→	}
   626→
   627→	// Set strategy if provided
   628→	if strategyName != "" {
   629→		// Map display name to internal name if needed
   630→		internalStrategy := strategyName
   631→		if mapped, ok := strategyDisplayToInternal[strategyName]; ok {
   632→			internalStrategy = mapped
   633→		}
   634→		// Validate the strategy exists
   635→		if _, err := strategy.Get(internalStrategy); err != nil {
   636→			return fmt.Errorf("unknown strategy: %s (use manual-commit or auto-commit)", strategyName)
   637→		}
   638→		settings.Strategy = internalStrategy
   639→	}
   640→
   641→	// Handle telemetry for non-interactive mode
   642→	// Note: if telemetry is nil (not configured), it defaults to disabled
   643→	if !telemetry || os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   644→		f := false
   645→		settings.Telemetry = &f
   646→	}
   647→
   648→	if err := SaveEntireSettings(settings); err != nil {
   649→		return fmt.Errorf("failed to save settings: %w", err)
   650→	}
   651→
   652→	// Install git hooks (always reinstall to ensure they're up-to-date)
   653→	if _, err := strategy.InstallGitHook(true); err != nil {
   654→		return fmt.Errorf("failed to install git hooks: %w", err)
   655→	}
   656→
   657→	// Let the strategy handle its own setup requirements (creates entire/sessions branch, etc.)
   658→	strat, err := strategy.Get(settings.Strategy)
   659→	if err != nil {
   660→		return fmt.Errorf("failed to get strategy: %w", err)
   661→	}
   662→	if err := strat.EnsureSetup(); err != nil {
   663→		return fmt.Errorf("failed to setup strategy: %w", err)
   664→	}
   665→
   666→	return nil
   667→}
