    21→
    22→	client := NewClient("1.0.0", nil)
    23→
    24→	if _, ok := client.(*NoOpClient); !ok {
    25→		t.Error("ENTIRE_TELEMETRY_OPTOUT with any value should return NoOpClient")
    26→	}
    27→}
