    30→	disabled := false
    31→	client := NewClient("1.0.0", &disabled)
    32→
    33→	if _, ok := client.(*NoOpClient); !ok {
    34→		t.Error("telemetryEnabled=false should return NoOpClient")
    35→	}
    36→}
