    38→func TestNewClientNilTelemetryDefaultsToDisabled(t *testing.T) {
    39→	// Ensure no opt-out env var is set
    40→	t.Setenv("ENTIRE_TELEMETRY_OPTOUT", "")
    41→
    42→	client := NewClient("1.0.0", nil)
    43→
    44→	if _, ok := client.(*NoOpClient); !ok {
    45→		t.Error("telemetryEnabled=nil should return NoOpClient (disabled by default)")
    46→	}
    47→}
    48→
    49→func TestNoOpClientMethods(_ *testing.T) {
    50→	client := &NoOpClient{}
    51→
    52→	// Should not panic
    53→	client.TrackCommand(nil, "", "", false)
    54→	client.TrackCommand(&cobra.Command{Use: "test"}, "manual-commit", "claude-code", true)
    55→	client.Close()
    56→}
    57→
