   547→// setupClaudeCodeHook sets up Claude Code hooks.
   548→// This is a convenience wrapper that uses the agent package.
   549→// Returns the number of hooks installed (0 if already installed).
   550→func setupClaudeCodeHook(localDev, forceHooks bool) (int, error) {
   551→	ag, err := agent.Get(agent.AgentNameClaudeCode)
