    65→
    66→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
    67→// then applies any overrides from .entire/settings.local.json if it exists.
    68→// Returns default settings if neither file exists.
    69→// Works correctly from any subdirectory within the repository.
    70→func LoadEntireSettings() (*EntireSettings, error) {
    71→	settings := &EntireSettings{
    72→		Strategy: strategy.DefaultStrategyName,
    73→		Enabled:  true, // Default to enabled
    74→	}
    75→
    76→	// Get absolute paths for settings files
    77→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    78→	if err != nil {
    79→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    80→	}
    81→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    82→	if err != nil {
    83→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    84→	}
    85→
    86→	// Load base settings
    87→	data, err := os.ReadFile(settingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    88→	if err != nil {
    89→		if !os.IsNotExist(err) {
    90→			return nil, fmt.Errorf("reading settings file: %w", err)
    91→		}
    92→		// File doesn't exist, continue with defaults
    93→	} else {
    94→		if err := json.Unmarshal(data, settings); err != nil {
    95→			return nil, fmt.Errorf("parsing settings file: %w", err)
    96→		}
    97→	}
    98→
    99→	// Apply local overrides if they exist
   100→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
   101→	if err != nil {
   102→		if !os.IsNotExist(err) {
   103→			return nil, fmt.Errorf("reading local settings file: %w", err)
   104→		}
   105→		// Local file doesn't exist, continue without overrides
   106→	} else {
   107→		if err := mergeSettingsJSON(settings, localData); err != nil {
   108→			return nil, fmt.Errorf("merging local settings: %w", err)
   109→		}
   110→	}
   111→
   112→	// Apply defaults if not set
   113→	if settings.Strategy == "" {
   114→		settings.Strategy = strategy.DefaultStrategyName
   115→	}
   116→	settings.Strategy = strategy.NormalizeStrategyName(settings.Strategy)
   117→
   118→	return settings, nil
   119→}
   120→
   121→// mergeSettingsJSON merges JSON data into existing settings.
   122→// Only non-zero values from the JSON override existing settings.
   123→func mergeSettingsJSON(settings *EntireSettings, data []byte) error {
   124→	// Parse into a map to check which fields are present
   125→	var raw map[string]json.RawMessage
   126→	if err := json.Unmarshal(data, &raw); err != nil {
   127→		return fmt.Errorf("parsing JSON: %w", err)
   128→	}
   129→
   130→	// Override strategy if present and non-empty
   131→	if strategyRaw, ok := raw["strategy"]; ok {
   132→		var s string
   133→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   134→			return fmt.Errorf("parsing strategy field: %w", err)
   135→		}
   136→		if s != "" {
   137→			settings.Strategy = s
   138→		}
   139→	}
   140→
   141→	// Override enabled if present
   142→	if enabledRaw, ok := raw["enabled"]; ok {
   143→		var e bool
   144→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   145→			return fmt.Errorf("parsing enabled field: %w", err)
   146→		}
   147→		settings.Enabled = e
   148→	}
   149→
   150→	// Override local_dev if present
   151→	if localDevRaw, ok := raw["local_dev"]; ok {
   152→		var ld bool
   153→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   154→			return fmt.Errorf("parsing local_dev field: %w", err)
   155→		}
   156→		settings.LocalDev = ld
   157→	}
   158→
   159→	// Override log_level if present and non-empty
   160→	if logLevelRaw, ok := raw["log_level"]; ok {
   161→		var ll string
   162→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   163→			return fmt.Errorf("parsing log_level field: %w", err)
   164→		}
   165→		if ll != "" {
   166→			settings.LogLevel = ll
   167→		}
   168→	}
   169→
   170→	// Merge strategy_options if present
   171→	if optionsRaw, ok := raw["strategy_options"]; ok {
   172→		var opts map[string]interface{}
   173→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   174→			return fmt.Errorf("parsing strategy_options field: %w", err)
   175→		}
   176→		if settings.StrategyOptions == nil {
   177→			settings.StrategyOptions = opts
   178→		} else {
   179→			for k, v := range opts {
   180→				settings.StrategyOptions[k] = v
   181→			}
   182→		}
   183→	}
   184→
   185→	// Override agent if present and non-empty
   186→	if agentRaw, ok := raw["agent"]; ok {
   187→		var a string
   188→		if err := json.Unmarshal(agentRaw, &a); err != nil {
   189→			return fmt.Errorf("parsing agent field: %w", err)
   190→		}
   191→		if a != "" {
   192→			settings.Agent = a
   193→		}
   194→	}
   195→
   196→	// Override agent_auto_detect if present
   197→	if autoDetectRaw, ok := raw["agent_auto_detect"]; ok {
   198→		var ad bool
   199→		if err := json.Unmarshal(autoDetectRaw, &ad); err != nil {
   200→			return fmt.Errorf("parsing agent_auto_detect field: %w", err)
   201→		}
   202→		settings.AgentAutoDetect = &ad
   203→	}
   204→
   205→	// Merge agent_options if present
   206→	if agentOptsRaw, ok := raw["agent_options"]; ok {
   207→		var opts map[string]interface{}
   208→		if err := json.Unmarshal(agentOptsRaw, &opts); err != nil {
   209→			return fmt.Errorf("parsing agent_options field: %w", err)
   210→		}
   211→		if settings.AgentOptions == nil {
   212→			settings.AgentOptions = opts
   213→		} else {
   214→			for k, v := range opts {
   215→				settings.AgentOptions[k] = v
   216→			}
   217→		}
   218→	}
   219→
   220→	// Override telemetry if present
   221→	if telemetryRaw, ok := raw["telemetry"]; ok {
   222→		var t bool
   223→		if err := json.Unmarshal(telemetryRaw, &t); err != nil {
   224→			return fmt.Errorf("parsing telemetry field: %w", err)
   225→		}
   226→		settings.Telemetry = &t
   227→	}
   228→
   229→	return nil
   230→}
   231→
   232→// SaveEntireSettings saves the Entire settings to .entire/settings.json.
   233→func SaveEntireSettings(settings *EntireSettings) error {
   234→	return saveSettingsToFile(settings, EntireSettingsFile)
   235→}
   236→
   237→// SaveEntireSettingsLocal saves the Entire settings to .entire/settings.local.json.
   238→func SaveEntireSettingsLocal(settings *EntireSettings) error {
   239→	return saveSettingsToFile(settings, EntireSettingsLocalFile)
   240→}
   241→
   242→func saveSettingsToFile(settings *EntireSettings, filePath string) error {
   243→	// Get absolute path for the file
   244→	filePathAbs, err := paths.AbsPath(filePath)
   245→	if err != nil {
   246→		filePathAbs = filePath // Fallback to relative
   247→	}
   248→
   249→	// Ensure directory exists
   250→	dir := filepath.Dir(filePathAbs)
   251→	if err := os.MkdirAll(dir, 0o750); err != nil {
   252→		return fmt.Errorf("creating settings directory: %w", err)
   253→	}
   254→
   255→	data, err := jsonutil.MarshalIndentWithNewline(settings, "", "  ")
   256→	if err != nil {
   257→		return fmt.Errorf("marshaling settings: %w", err)
   258→	}
   259→
   260→	//nolint:gosec // G306: settings file is config, not secrets; 0o644 is appropriate
   261→	if err := os.WriteFile(filePathAbs, data, 0o644); err != nil {
   262→		return fmt.Errorf("writing settings file: %w", err)
   263→	}
   264→	return nil
   265→}
   266→
   267→// IsEnabled returns whether Entire is currently enabled.
   268→// Returns true by default if settings cannot be loaded.
   269→func IsEnabled() (bool, error) {
   270→	settings, err := LoadEntireSettings()
   271→	if err != nil {
   272→		return true, err
   273→	}
   274→	return settings.Enabled, nil
   275→}
   276→
   277→// GetStrategy returns the configured strategy instance.
   278→// Falls back to default if the configured strategy is not found.
   279→//
   280→//nolint:ireturn // Factory pattern requires returning the interface
   281→func GetStrategy() strategy.Strategy {
   282→	settings, err := LoadEntireSettings()
   283→	if err != nil {
   284→		// Fall back to default on error
   285→		logging.Info(context.Background(), "falling back to default strategy - failed to load settings",
   286→			slog.String("error", err.Error()))
   287→		return strategy.Default()
   288→	}
   289→
   290→	s, err := strategy.Get(settings.Strategy)
   291→	if err != nil {
   292→		// Fall back to default if strategy not found
   293→		logging.Info(context.Background(), "falling back to default strategy - configured strategy not found",
   294→			slog.String("configured", settings.Strategy),
   295→			slog.String("error", err.Error()))
   296→		return strategy.Default()
   297→	}
   298→
   299→	return s
   300→}
   301→
   302→// GetAgent returns the configured or detected agent.
   303→// Resolution order:
   304→// 1. Explicit agent in settings
   305→// 2. Auto-detect if enabled (default)
   306→// 3. Fall back to default agent
   307→//
   308→//nolint:ireturn // Factory pattern requires returning the interface
   309→func GetAgent() (agent.Agent, error) {
   310→	settings, err := LoadEntireSettings()
   311→	if err != nil {
   312→		// No settings file, try auto-detect then default
   313→		if ag, detectErr := agent.Detect(); detectErr == nil {
   314→			return ag, nil
   315→		}
   316→		return agent.Default(), nil
   317→	}
   318→
   319→	// Explicit agent configured
   320→	if settings.Agent != "" {
   321→		ag, err := agent.Get(agent.AgentName(settings.Agent))
   322→		if err != nil {
   323→			return nil, fmt.Errorf("getting configured agent: %w", err)
   324→		}
   325→		return ag, nil
   326→	}
   327→
   328→	// Auto-detect if enabled (default true for backwards compat)
   329→	autoDetect := settings.AgentAutoDetect == nil || *settings.AgentAutoDetect
   330→	if autoDetect {
   331→		if ag, detectErr := agent.Detect(); detectErr == nil {
   332→			return ag, nil
   333→		}
   334→	}
   335→
   336→	// Fall back to default
   337→	return agent.Default(), nil
   338→}
   339→
   340→// GetAgentOptions returns options for a specific agent.
   341→// Returns nil if the agent has no options configured.
   342→func GetAgentOptions(agentName string) map[string]interface{} {
   343→	settings, err := LoadEntireSettings()
   344→	if err != nil {
   345→		return nil
   346→	}
   347→
   348→	if settings.AgentOptions == nil {
   349→		return nil
   350→	}
   351→
   352→	if opts, ok := settings.AgentOptions[agentName]; ok {
   353→		if m, ok := opts.(map[string]interface{}); ok {
   354→			return m
   355→		}
   356→	}
   357→	return nil
   358→}
   359→
   360→// GetLogLevel returns the configured log level from settings.
   361→// Returns empty string if not configured (caller should use default).
   362→// Note: ENTIRE_LOG_LEVEL env var takes precedence; check it first.
