   808→// promptShellCompletion offers to add shell completion to the user's rc file.
   809→// Only prompts if completion is not already configured.
   810→func promptShellCompletion(w io.Writer) error {
   811→	// Get user's home directory
   812→	home, err := os.UserHomeDir()
   813→	if err != nil {
   814→		//nolint:nilerr // Skip silently if we can't determine home - not a fatal error
   815→		return nil
   816→	}
   817→
   818→	// Determine shell and rc file
   819→	shell := os.Getenv("SHELL")
   820→	var rcFile string
   821→	var completionLine string
   822→
   823→	switch {
   824→	case strings.Contains(shell, "zsh"):
   825→		rcFile = filepath.Join(home, ".zshrc")
   826→		completionLine = "source <(entire completion zsh)"
   827→	case strings.Contains(shell, "bash"):
   828→		rcFile = filepath.Join(home, ".bashrc")
   829→		completionLine = "source <(entire completion bash)"
   830→	default:
   831→		return nil // Unsupported shell, skip silently
   832→	}
   833→
   834→	// Check if completion is already configured
   835→	if isCompletionConfigured(rcFile) {
   836→		return nil // Already configured, skip silently
   837→	}
   838→
   839→	// Prompt user with select-style picker (matching other prompts)
   840→	var selected string
   841→	form := NewAccessibleForm(
   842→		huh.NewGroup(
   843→			huh.NewSelect[string]().
   844→				Title("Enable shell completion?").
   845→				Options(
   846→					huh.NewOption("Yes", "yes"),
   847→					huh.NewOption("No", "no"),
   848→				).
   849→				Value(&selected),
   850→		),
   851→	)
   852→
   853→	if err := form.Run(); err != nil {
   854→		//nolint:nilerr // User cancelled - not a fatal error, just skip
   855→		return nil
   856→	}
   857→
   858→	if selected != "yes" {
   859→		return nil
   860→	}
   861→
   862→	// Append completion to rc file
   863→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   864→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   865→	}
   866→
   867→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   868→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   869→
   870→	return nil
   871→}
   872→
   873→// isCompletionConfigured checks if shell completion is already in the rc file.
   874→func isCompletionConfigured(rcFile string) bool {
   875→	//nolint:gosec // G304: rcFile is constructed from home dir + known filename, not user input
   876→	content, err := os.ReadFile(rcFile)
   877→	if err != nil {
   878→		return false // File doesn't exist or can't read, treat as not configured
   879→	}
   880→	return strings.Contains(string(content), "entire completion")
   881→}
   882→
   883→// appendShellCompletion adds the completion line to the rc file.
   884→func appendShellCompletion(rcFile, completionLine string) error {
   885→	//nolint:gosec // G302: Shell rc files need 0644 for user readability
   886→	f, err := os.OpenFile(rcFile, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
   887→	if err != nil {
   888→		return fmt.Errorf("opening file: %w", err)
   889→	}
   890→	defer f.Close()
   891→
   892→	// Add newline, comment, and completion line
   893→	_, err = f.WriteString("\n" + shellCompletionComment + "\n" + completionLine + "\n")
   894→	if err != nil {
   895→		return fmt.Errorf("writing completion: %w", err)
   896→	}
   897→	return nil
   898→}
   899→
   900→// setupShellCompletionNonInteractive adds shell completion without prompting.
   901→// Used when --setup-shell flag is provided.
   902→func setupShellCompletionNonInteractive(w io.Writer) error {
   903→	// Get user's home directory
   904→	home, err := os.UserHomeDir()
   905→	if err != nil {
   906→		return fmt.Errorf("cannot determine home directory: %w", err)
   907→	}
   908→
   909→	// Determine shell and rc file
   910→	shell := os.Getenv("SHELL")
   911→	var rcFile string
   912→	var completionLine string
   913→
   914→	switch {
   915→	case strings.Contains(shell, "zsh"):
   916→		rcFile = filepath.Join(home, ".zshrc")
   917→		completionLine = "source <(entire completion zsh)"
   918→	case strings.Contains(shell, "bash"):
   919→		rcFile = filepath.Join(home, ".bashrc")
   920→		completionLine = "source <(entire completion bash)"
   921→	default:
   922→		return fmt.Errorf("unsupported shell: %s (supported: zsh, bash)", shell)
   923→	}
   924→
   925→	// Check if completion is already configured
   926→	if isCompletionConfigured(rcFile) {
   927→		fmt.Fprintf(w, "✓ Shell completion already configured in %s\n", rcFile)
   928→		return nil
   929→	}
   930→
   931→	// Append completion to rc file
   932→	if err := appendShellCompletion(rcFile, completionLine); err != nil {
   933→		return fmt.Errorf("failed to update %s: %w", rcFile, err)
   934→	}
   935→
   936→	fmt.Fprintf(w, "✓ Shell completion added to %s\n", rcFile)
   937→	fmt.Fprintln(w, "  Run `source "+rcFile+"` or restart your shell to activate")
   938→
   939→	return nil
   940→}
   941→
   942→// promptTelemetryConsent asks the user if they want to enable telemetry.
   943→// It modifies settings.Telemetry based on the user's choice or flags.
   944→// The caller is responsible for saving settings.
   945→func promptTelemetryConsent(settings *EntireSettings, telemetryFlag bool) error {
   946→	// Handle --telemetry=false flag first (always overrides existing setting)
   947→	if !telemetryFlag {
   948→		f := false
   949→		settings.Telemetry = &f
   950→		return nil
   951→	}
   952→
   953→	// Skip if already asked
   954→	if settings.Telemetry != nil {
   955→		return nil
   956→	}
   957→
   958→	// Skip if env var disables telemetry (record as disabled)
   959→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
   960→		f := false
   961→		settings.Telemetry = &f
   962→		return nil
   963→	}
   964→
   965→	consent := true // Default to Yes
   966→	form := NewAccessibleForm(
   967→		huh.NewGroup(
   968→			huh.NewConfirm().
   969→				Title("Help improve Entire CLI?").
   970→				Description("Share anonymous usage data. No code or personal info collected.").
   971→				Affirmative("Yes").
   972→				Negative("No").
   973→				Value(&consent),
   974→		),
   975→	)
   976→
   977→	if err := form.Run(); err != nil {
   978→		return fmt.Errorf("telemetry prompt: %w", err)
   979→	}
   980→
   981→	settings.Telemetry = &consent
   982→	return nil
   983→}
   984→
   985→// runUninstall completely removes Entire from the repository.
   986→func runUninstall(w, errW io.Writer, force bool) error {
   987→	// Check if we're in a git repository
   988→	if _, err := paths.RepoRoot(); err != nil {
   989→		fmt.Fprintln(errW, "Not a git repository. Nothing to uninstall.")
   990→		return NewSilentError(errors.New("not a git repository"))
   991→	}
   992→
   993→	// Gather counts for display
   994→	sessionStateCount := countSessionStates()
   995→	shadowBranchCount := countShadowBranches()
   996→	gitHooksInstalled := strategy.IsGitHookInstalled()
   997→	claudeHooksInstalled := checkClaudeCodeHooksInstalled()
   998→	geminiHooksInstalled := checkGeminiCLIHooksInstalled()
   999→	entireDirExists := checkEntireDirExists()
  1000→
  1001→	// Check if there's anything to uninstall
  1002→	if !entireDirExists && !gitHooksInstalled && sessionStateCount == 0 &&
  1003→		shadowBranchCount == 0 && !claudeHooksInstalled && !geminiHooksInstalled {
  1004→		fmt.Fprintln(w, "Entire is not installed in this repository.")
  1005→		return nil
  1006→	}
  1007→
  1008→	// Show confirmation prompt unless --force
  1009→	if !force {
  1010→		fmt.Fprintln(w, "\nThis will completely remove Entire from this repository:")
  1011→		if entireDirExists {
  1012→			fmt.Fprintln(w, "  - .entire/ directory")
  1013→		}
  1014→		if gitHooksInstalled {
  1015→			fmt.Fprintln(w, "  - Git hooks (prepare-commit-msg, commit-msg, post-commit, pre-push)")
  1016→		}
  1017→		if sessionStateCount > 0 {
  1018→			fmt.Fprintf(w, "  - Session state files (%d)\n", sessionStateCount)
  1019→		}
  1020→		if shadowBranchCount > 0 {
  1021→			fmt.Fprintf(w, "  - Shadow branches (%d)\n", shadowBranchCount)
  1022→		}
  1023→		switch {
  1024→		case claudeHooksInstalled && geminiHooksInstalled:
  1025→			fmt.Fprintln(w, "  - Agent hooks (Claude Code, Gemini CLI)")
  1026→		case claudeHooksInstalled:
  1027→			fmt.Fprintln(w, "  - Agent hooks (Claude Code)")
  1028→		case geminiHooksInstalled:
  1029→			fmt.Fprintln(w, "  - Agent hooks (Gemini CLI)")
  1030→		}
  1031→		fmt.Fprintln(w)
  1032→
  1033→		var confirmed bool
  1034→		form := NewAccessibleForm(
  1035→			huh.NewGroup(
  1036→				huh.NewConfirm().
  1037→					Title("Are you sure you want to uninstall Entire?").
  1038→					Affirmative("Yes, uninstall").
  1039→					Negative("Cancel").
  1040→					Value(&confirmed),
  1041→			),
  1042→		)
  1043→
  1044→		if err := form.Run(); err != nil {
  1045→			return fmt.Errorf("confirmation cancelled: %w", err)
  1046→		}
  1047→
  1048→		if !confirmed {
  1049→			fmt.Fprintln(w, "Uninstall cancelled.")
  1050→			return nil
  1051→		}
  1052→	}
  1053→
  1054→	fmt.Fprintln(w, "\nUninstalling Entire CLI...")
  1055→
  1056→	// 1. Remove agent hooks (lowest risk)
  1057→	if err := removeAgentHooks(w); err != nil {
  1058→		fmt.Fprintf(errW, "Warning: failed to remove agent hooks: %v\n", err)
  1059→	}
  1060→
  1061→	// 2. Remove git hooks
  1062→	removed, err := strategy.RemoveGitHook()
  1063→	if err != nil {
  1064→		fmt.Fprintf(errW, "Warning: failed to remove git hooks: %v\n", err)
  1065→	} else if removed > 0 {
  1066→		fmt.Fprintf(w, "  Removed git hooks (%d)\n", removed)
  1067→	}
  1068→
  1069→	// 3. Remove session state files
  1070→	statesRemoved, err := removeAllSessionStates()
  1071→	if err != nil {
  1072→		fmt.Fprintf(errW, "Warning: failed to remove session states: %v\n", err)
  1073→	} else if statesRemoved > 0 {
  1074→		fmt.Fprintf(w, "  Removed session states (%d)\n", statesRemoved)
  1075→	}
  1076→
  1077→	// 4. Remove .entire/ directory
  1078→	if err := removeEntireDirectory(); err != nil {
  1079→		fmt.Fprintf(errW, "Warning: failed to remove .entire directory: %v\n", err)
  1080→	} else if entireDirExists {
  1081→		fmt.Fprintln(w, "  Removed .entire directory")
  1082→	}
  1083→
  1084→	// 5. Remove shadow branches
  1085→	branchesRemoved, err := removeAllShadowBranches()
  1086→	if err != nil {
  1087→		fmt.Fprintf(errW, "Warning: failed to remove shadow branches: %v\n", err)
  1088→	} else if branchesRemoved > 0 {
  1089→		fmt.Fprintf(w, "  Removed %d shadow branches\n", branchesRemoved)
  1090→	}
  1091→
  1092→	fmt.Fprintln(w, "\nEntire CLI uninstalled successfully.")
  1093→	return nil
  1094→}
  1095→
  1096→// countSessionStates returns the number of active session state files.
  1097→func countSessionStates() int {
  1098→	store, err := session.NewStateStore()
  1099→	if err != nil {
  1100→		return 0
  1101→	}
  1102→	states, err := store.List(context.Background())
  1103→	if err != nil {
  1104→		return 0
  1105→	}
  1106→	return len(states)
  1107→}
  1108→
  1109→// countShadowBranches returns the number of shadow branches.
  1110→func countShadowBranches() int {
  1111→	branches, err := strategy.ListShadowBranches()
  1112→	if err != nil {
  1113→		return 0
  1114→	}
  1115→	return len(branches)
  1116→}
  1117→
  1118→// checkClaudeCodeHooksInstalled checks if Claude Code hooks are installed.
  1119→func checkClaudeCodeHooksInstalled() bool {
  1120→	ag, err := agent.Get(agent.AgentNameClaudeCode)
  1121→	if err != nil {
  1122→		return false
  1123→	}
  1124→	hookAgent, ok := ag.(agent.HookSupport)
  1125→	if !ok {
  1126→		return false
  1127→	}
  1128→	return hookAgent.AreHooksInstalled()
  1129→}
  1130→
  1131→// checkGeminiCLIHooksInstalled checks if Gemini CLI hooks are installed.
  1132→func checkGeminiCLIHooksInstalled() bool {
  1133→	ag, err := agent.Get(agent.AgentNameGemini)
  1134→	if err != nil {
  1135→		return false
  1136→	}
  1137→	hookAgent, ok := ag.(agent.HookSupport)
  1138→	if !ok {
  1139→		return false
  1140→	}
