func TestNoOpClientMethods(_ *testing.T) {
	client := &NoOpClient{}

	// Should not panic
	client.TrackCommand(nil, "", "", false)
	client.TrackCommand(&cobra.Command{Use: "test"}, "manual-commit", "claude-code", true)
