package telemetry

import (
	"net"
	"net/http"
	"os"
	"runtime"
	"strings"
	"sync"
	"time"

	"github.com/denisbrodbeck/machineid"
	"github.com/posthog/posthog-go"
	"github.com/spf13/cobra"
	"github.com/spf13/pflag"
)

var (
	// PostHogAPIKey is set at build time for production
	PostHogAPIKey = "phc_development_key"
	// PostHogEndpoint is set at build time for production
	PostHogEndpoint = "https://eu.i.posthog.com"
)

// Client defines the telemetry interface
type Client interface {
	TrackCommand(cmd *cobra.Command, strategy string, agent string, isEntireEnabled bool)
	Close()
}

// NoOpClient is a no-op implementation for when telemetry is disabled
type NoOpClient struct{}

func (n *NoOpClient) TrackCommand(_ *cobra.Command, _ string, _ string, _ bool) {}
func (n *NoOpClient) Close()                                                    {}

// silentLogger suppresses PostHog log output - expected for CLI best-effort telemetry
type silentLogger struct{}

func (silentLogger) Logf(_ string, _ ...interface{})   {}
func (silentLogger) Debugf(_ string, _ ...interface{}) {}
func (silentLogger) Warnf(_ string, _ ...interface{})  {}
func (silentLogger) Errorf(_ string, _ ...interface{}) {}

// PostHogClient is the real telemetry client
type PostHogClient struct {
	client     posthog.Client
	machineID  string
	cliVersion string
	mu         sync.RWMutex
}

// NewClient creates a new telemetry client based on opt-out settings.
// The telemetryEnabled parameter comes from settings; nil means not configured (default to disabled).
//
//nolint:ireturn // Factory function - returns NoOpClient or PostHogClient based on settings
func NewClient(version string, telemetryEnabled *bool) Client {
	// Environment variable takes priority
	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
		return &NoOpClient{}
	}

	// Check settings preference (nil = not set, default to disabled)
	if telemetryEnabled == nil || !*telemetryEnabled {
		return &NoOpClient{}
	}

	id, err := machineid.ProtectedID("entire-cli")
	if err != nil {
		return &NoOpClient{}
	}

	// Use a fast-timeout HTTP transport for telemetry - we don't want to block CLI exit
	transport := &http.Transport{
		DialContext: (&net.Dialer{
			Timeout: 100 * time.Millisecond,
		}).DialContext,
		TLSHandshakeTimeout:   100 * time.Millisecond,
		ResponseHeaderTimeout: 100 * time.Millisecond,
	}

	client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
		Endpoint:           PostHogEndpoint,
		ShutdownTimeout:    100 * time.Millisecond, // Don't block CLI exit waiting for telemetry
		BatchUploadTimeout: 200 * time.Millisecond, // Fast timeout - telemetry is best-effort
		Transport:          transport,
		Logger:             silentLogger{}, // Suppress warnings on timeout (expected)
		DisableGeoIP:       posthog.Ptr(true),
		DefaultEventProperties: posthog.NewProperties().
			Set("cli_version", version).
			Set("os", runtime.GOOS).
			Set("arch", runtime.GOARCH),
	})
	if err != nil {
		return &NoOpClient{}
	}

	return &PostHogClient{
		client:     client,
		machineID:  id,
		cliVersion: version,
	}
}

// TrackCommand records the command execution
func (p *PostHogClient) TrackCommand(cmd *cobra.Command, strategy string, agent string, isEntireEnabled bool) {
	if cmd == nil {
		return
	}

	// Skip hidden commands
	if cmd.Hidden {
		return
	}

	p.mu.RLock()
	id := p.machineID
	c := p.client
	p.mu.RUnlock()

	if c == nil {
		return
	}

	// Collect flag names (not values) for privacy
	var flags []string
	cmd.Flags().Visit(func(flag *pflag.Flag) {
		flags = append(flags, flag.Name)
	})

	selectedAgent := agent
	if selectedAgent == "" {
		selectedAgent = "auto"
	}
	props := posthog.NewProperties().
		Set("command", cmd.CommandPath()).
		Set("strategy", strategy).
		Set("agent", selectedAgent).
		Set("isEntireEnabled", isEntireEnabled)

	if len(flags) > 0 {
		props.Set("flags", strings.Join(flags, ","))
	}

	//nolint:errcheck // Best-effort telemetry, failures should not affect CLI
	_ = c.Enqueue(posthog.Capture{
		DistinctId: id,
		Event:      "cli_command_executed",
		Properties: props,
	})
}

// Close flushes pending events
func (p *PostHogClient) Close() {
	p.mu.RLock()
	c := p.client
	p.mu.RUnlock()

	if c != nil {
		_ = c.Close()
	}
}

package cli

import (
	"fmt"
	"runtime"

	"entire.io/cli/cmd/entire/cli/telemetry"
	"github.com/spf13/cobra"
)

const gettingStarted = `

Getting Started:
  To get started with Entire CLI, run 'entire enable' to configure
  your environment. For more information, visit:
  https://entire.io/docs/cli/getting-started

`

const accessibilityHelp = `
Environment Variables:
  ACCESSIBLE    Set to any value (e.g., ACCESSIBLE=1) to enable accessibility
                mode. This uses simpler text prompts instead of interactive
                TUI elements, which works better with screen readers.
`

// Version information (can be set at build time)
var (
	Version = "dev"
	Commit  = "unknown"
)

func NewRootCmd() *cobra.Command {
	cmd := &cobra.Command{
		Use:   "entire",
		Short: "Entire CLI",
		Long:  "A command-line interface for Entire" + gettingStarted + accessibilityHelp,
		// Let main.go handle error printing to avoid duplication
		SilenceErrors: true,
		// Hide completion command from help but keep it functional
		CompletionOptions: cobra.CompletionOptions{
			HiddenDefaultCmd: true,
		},
		PersistentPostRun: func(cmd *cobra.Command, _ []string) {
			// Load telemetry preference from settings (ignore errors - nil defaults to disabled)
			var telemetryEnabled *bool
			settings, err := LoadEntireSettings()
			if err == nil {
				telemetryEnabled = settings.Telemetry
			}

			// Initialize telemetry client and add to context
			telemetryClient := telemetry.NewClient(Version, telemetryEnabled)
			defer telemetryClient.Close()
			telemetryClient.TrackCommand(cmd, settings.Strategy, settings.Agent, settings.Enabled)
		},
		RunE: func(cmd *cobra.Command, _ []string) error {
			return cmd.Help()
		},
	}

	// Add subcommands here
	cmd.AddCommand(newRewindCmd())
	cmd.AddCommand(newResumeCmd())
	cmd.AddCommand(newCleanCmd())
	cmd.AddCommand(newEnableCmd())
	cmd.AddCommand(newDisableCmd())
	cmd.AddCommand(newStatusCmd())
	cmd.AddCommand(newHooksCmd())
	cmd.AddCommand(newVersionCmd())
	cmd.AddCommand(newExplainCmd())
	cmd.AddCommand(newDebugCmd())

	// Replace default help command with custom one that supports -t flag
	cmd.SetHelpCommand(NewHelpCmd(cmd))

	return cmd
}

func newVersionCmd() *cobra.Command {
	return &cobra.Command{
		Use:   "version",
		Short: "Show version information",
		Run: func(_ *cobra.Command, _ []string) {
			fmt.Printf("Entire CLI %s (%s)\n", Version, Commit)
			fmt.Printf("Go version: %s\n", runtime.Version())
			fmt.Printf("OS/Arch: %s/%s\n", runtime.GOOS, runtime.GOARCH)
		},
	}
}

# PostHog Async Analytics Implementation Plan

## Problem

PostHog Go SDK blocks on `client.Close()` waiting for events to flush. With the Europe endpoint from Tasmania/Australia, this adds ~1 second latency to every CLI command.

## Solution

Spawn a detached subprocess that sends analytics events independently. The parent CLI process exits immediately while the child process handles the HTTP request to PostHog.

## Architecture

```
CLI Command Execution
        │
        ├── Execute command logic
        │
        └── PersistentPostRun
                │
                └── TrackDetached()
                        │
                        ├── Serialize event to JSON
                        ├── Spawn detached subprocess (same binary)
                        └── Exit immediately (0ms latency)

                        Detached Subprocess (__send_analytics)
                                │
                                ├── Parse JSON payload
                                ├── Create PostHog client
                                ├── Enqueue event
                                └── client.Close() (blocks ~1s, but detached)
```

## Implementation Steps

### Step 1: Create analytics package

Create a new file `internal/analytics/tracker.go` (or appropriate path for your project structure):

```go
//go:build unix

package analytics

import (
    "encoding/json"
    "os"
    "os/exec"
    "syscall"
    "time"

    "github.com/posthog/posthog-go"
    "github.com/spf13/cobra"
)

const analyticsSubcmd = "__send_analytics"

var (
    apiKey   string
    endpoint string
)

// Init sets the PostHog configuration
func Init(key, ep string) {
    apiKey = key
    endpoint = ep
}

// TrackDetached sends an event via a detached subprocess (non-blocking)
func TrackDetached(event, distinctID string, properties map[string]any) {
    if apiKey == "" {
        return
    }

    payload, err := json.Marshal(map[string]any{
        "event":       event,
        "distinct_id": distinctID,
        "properties":  properties,
        "timestamp":   time.Now().UTC().Format(time.RFC3339),
    })
    if err != nil {
        return
    }

    exe, err := os.Executable()
    if err != nil {
        return
    }

    cmd := exec.Command(exe, analyticsSubcmd, string(payload))
    cmd.SysProcAttr = &syscall.SysProcAttr{
        Setpgid: true,
    }
    cmd.Stdin = nil
    cmd.Stdout = nil
    cmd.Stderr = nil
    cmd.Dir = "/"
    cmd.Env = os.Environ()

    _ = cmd.Start()
}

// RegisterCmd adds the hidden analytics subcommand to the root command
func RegisterCmd(rootCmd *cobra.Command) {
    rootCmd.AddCommand(&cobra.Command{
        Use:    analyticsSubcmd,
        Hidden: true,
        Args:   cobra.ExactArgs(1),
        Run:    runAnalyticsCmd,
    })
}

func runAnalyticsCmd(_ *cobra.Command, args []string) {
    var payload struct {
        Event      string         `json:"event"`
        DistinctID string         `json:"distinct_id"`
        Properties map[string]any `json:"properties"`
        Timestamp  string         `json:"timestamp"`
    }

    if err := json.Unmarshal([]byte(args[0]), &payload); err != nil {
        return
    }

    client, err := posthog.NewWithConfig(apiKey, posthog.Config{
        Endpoint: endpoint,
    })
    if err != nil {
        return
    }
    defer client.Close()

    ts, _ := time.Parse(time.RFC3339, payload.Timestamp)
    if ts.IsZero() {
        ts = time.Now()
    }

    client.Enqueue(posthog.Capture{
        DistinctId: payload.DistinctID,
        Event:      payload.Event,
        Properties: posthog.Properties(payload.Properties),
        Timestamp:  ts,
    })
}
```

### Step 2: Integrate with root command

In your root command file (e.g., `cmd/root.go`):

```go
package cmd

import (
    "os"

    "yourproject/internal/analytics"
    "github.com/spf13/cobra"
)

var rootCmd = &cobra.Command{
    Use:   "yourcli",
    Short: "Your CLI description",
    PersistentPostRun: func(cmd *cobra.Command, args []string) {
        // Skip tracking for the analytics subcommand itself
        if cmd.Name() == "__send_analytics" {
            return
        }

        analytics.TrackDetached("cli_command", getDistinctID(), map[string]any{
            "command": cmd.CommandPath(),
            "args":    len(args),
            // Add any other properties you want to track
        })
    },
}

func init() {
    // Initialize analytics
    analytics.Init(
        os.Getenv("POSTHOG_API_KEY"),      // or hardcode/config
        "https://eu.i.posthog.com",         // your endpoint
    )

    // Register the hidden analytics subcommand
    analytics.RegisterCmd(rootCmd)
}

func getDistinctID() string {
    // Return your user identifier
    // e.g., machine ID, config-stored UUID, etc.
    return "user-id"
}
```

### Step 3: Remove existing blocking PostHog code

Find and remove any existing PostHog tracking code that uses:
- `defer client.Close()`
- Direct `client.Enqueue()` calls in command handlers
- Any synchronous PostHog client usage

### Step 4: Test the implementation

1. Build the CLI:
   ```bash
   go build -o mycli .
   ```

2. Run a command and verify it exits immediately:
   ```bash
   time ./mycli some-command
   # Should complete in normal time without ~1s delay
   ```

3. Verify events arrive in PostHog dashboard (may take a few seconds)

4. Check for zombie processes:
   ```bash
   ps aux | grep __send_analytics
   # Should show briefly then disappear
   ```

## Configuration Options

### Environment-based opt-out

Add analytics opt-out support:

```go
func TrackDetached(event, distinctID string, properties map[string]any) {
    if apiKey == "" || os.Getenv("DO_NOT_TRACK") == "1" {
        return
    }
    // ... rest of function
}
```

### Debug mode

Add optional logging for debugging:

```go
func TrackDetached(event, distinctID string, properties map[string]any) {
    if os.Getenv("ANALYTICS_DEBUG") == "1" {
        fmt.Fprintf(os.Stderr, "[analytics] tracking: %s\n", event)
    }
    // ... rest of function
}
```

## Files to Create/Modify

- [ ] Create `internal/analytics/tracker.go` (new file)
- [ ] Modify `cmd/root.go` to integrate analytics
- [ ] Remove old PostHog tracking code (search for existing `posthog` imports)
- [ ] Update `.gitignore` if needed for any local config

## Verification Checklist

- [ ] CLI commands execute without latency delay
- [ ] Events appear in PostHog dashboard
- [ ] No zombie processes after CLI exits
- [ ] Works on both Linux and macOS
- [ ] Analytics opt-out via `DO_NOT_TRACK=1` works
- [ ] Hidden `__send_analytics` command doesn't appear in help

