    14→	"entire.io/cli/cmd/entire/cli/paths"
    15→	"entire.io/cli/cmd/entire/cli/strategy"
    16→
    17→	// Import claudecode to register the agent
    18→	_ "entire.io/cli/cmd/entire/cli/agent/claudecode"
    19→)
    20→
    21→const (
    22→	// EntireSettingsFile is the path to the Entire settings file
    23→	EntireSettingsFile = ".entire/settings.json"
    24→	// EntireSettingsLocalFile is the path to the local settings override file (not committed)
    25→	EntireSettingsLocalFile = ".entire/settings.local.json"
    26→)
    27→
    28→// EntireSettings represents the .entire/settings.json configuration
    29→type EntireSettings struct {
    30→	// Strategy is the name of the git strategy to use
    31→	Strategy string `json:"strategy"`
    32→
    33→	// Agent is the name of the coding agent (e.g., "claude-code", "cursor")
    34→	// When empty, auto-detection is used
    35→	Agent string `json:"agent,omitempty"`
    36→
    37→	// AgentAutoDetect controls whether to auto-detect the agent when not explicitly set
    38→	// Defaults to true for backwards compatibility
    39→	AgentAutoDetect *bool `json:"agent_auto_detect,omitempty"`
    40→
    41→	// Enabled indicates whether Entire is active. When false, CLI commands
    42→	// show a disabled message and hooks exit silently. Defaults to true.
    43→	Enabled bool `json:"enabled"`
    44→
    45→	// LocalDev indicates whether to use "go run" instead of the "entire" binary
    46→	// This is used for development when the binary is not installed
    47→	LocalDev bool `json:"local_dev,omitempty"`
    48→
    49→	// LogLevel sets the logging verbosity (debug, info, warn, error).
    50→	// Can be overridden by ENTIRE_LOG_LEVEL environment variable.
    51→	// Defaults to "info".
    52→	LogLevel string `json:"log_level,omitempty"`
    53→
    54→	// StrategyOptions contains strategy-specific configuration
    55→	StrategyOptions map[string]interface{} `json:"strategy_options,omitempty"`
    56→
    57→	// AgentOptions contains agent-specific configuration
    58→	// Keyed by agent name, e.g., {"claude-code": {"ignore_untracked": false}}
    59→	AgentOptions map[string]interface{} `json:"agent_options,omitempty"`
    60→
    61→	// Telemetry controls anonymous usage analytics.
    62→	// nil = not asked yet (show prompt), true = opted in, false = opted out
    63→	Telemetry *bool `json:"telemetry,omitempty"`
    64→}
    65→
    66→// LoadEntireSettings loads the Entire settings from .entire/settings.json,
    67→// then applies any overrides from .entire/settings.local.json if it exists.
    68→// Returns default settings if neither file exists.
    69→// Works correctly from any subdirectory within the repository.
    70→func LoadEntireSettings() (*EntireSettings, error) {
    71→	settings := &EntireSettings{
    72→		Strategy: strategy.DefaultStrategyName,
    73→		Enabled:  true, // Default to enabled
    74→	}
    75→
    76→	// Get absolute paths for settings files
    77→	settingsFileAbs, err := paths.AbsPath(EntireSettingsFile)
    78→	if err != nil {
    79→		settingsFileAbs = EntireSettingsFile // Fallback to relative
    80→	}
    81→	localSettingsFileAbs, err := paths.AbsPath(EntireSettingsLocalFile)
    82→	if err != nil {
    83→		localSettingsFileAbs = EntireSettingsLocalFile // Fallback to relative
    84→	}
    85→
    86→	// Load base settings
    87→	data, err := os.ReadFile(settingsFileAbs) //nolint:gosec // path is from AbsPath or constant
    88→	if err != nil {
    89→		if !os.IsNotExist(err) {
    90→			return nil, fmt.Errorf("reading settings file: %w", err)
    91→		}
    92→		// File doesn't exist, continue with defaults
    93→	} else {
    94→		if err := json.Unmarshal(data, settings); err != nil {
    95→			return nil, fmt.Errorf("parsing settings file: %w", err)
    96→		}
    97→	}
    98→
    99→	// Apply local overrides if they exist
   100→	localData, err := os.ReadFile(localSettingsFileAbs) //nolint:gosec // path is from AbsPath or constant
   101→	if err != nil {
   102→		if !os.IsNotExist(err) {
   103→			return nil, fmt.Errorf("reading local settings file: %w", err)
   104→		}
   105→		// Local file doesn't exist, continue without overrides
   106→	} else {
   107→		if err := mergeSettingsJSON(settings, localData); err != nil {
   108→			return nil, fmt.Errorf("merging local settings: %w", err)
   109→		}
   110→	}
   111→
   112→	// Apply defaults if not set
   113→	if settings.Strategy == "" {
   114→		settings.Strategy = strategy.DefaultStrategyName
   115→	}
   116→	settings.Strategy = strategy.NormalizeStrategyName(settings.Strategy)
   117→
   118→	return settings, nil
   119→}
   120→
   121→// mergeSettingsJSON merges JSON data into existing settings.
   122→// Only non-zero values from the JSON override existing settings.
   123→func mergeSettingsJSON(settings *EntireSettings, data []byte) error {
   124→	// Parse into a map to check which fields are present
   125→	var raw map[string]json.RawMessage
   126→	if err := json.Unmarshal(data, &raw); err != nil {
   127→		return fmt.Errorf("parsing JSON: %w", err)
   128→	}
   129→
   130→	// Override strategy if present and non-empty
   131→	if strategyRaw, ok := raw["strategy"]; ok {
   132→		var s string
   133→		if err := json.Unmarshal(strategyRaw, &s); err != nil {
   134→			return fmt.Errorf("parsing strategy field: %w", err)
   135→		}
   136→		if s != "" {
   137→			settings.Strategy = s
   138→		}
   139→	}
   140→
   141→	// Override enabled if present
   142→	if enabledRaw, ok := raw["enabled"]; ok {
   143→		var e bool
   144→		if err := json.Unmarshal(enabledRaw, &e); err != nil {
   145→			return fmt.Errorf("parsing enabled field: %w", err)
   146→		}
   147→		settings.Enabled = e
   148→	}
   149→
   150→	// Override local_dev if present
   151→	if localDevRaw, ok := raw["local_dev"]; ok {
   152→		var ld bool
   153→		if err := json.Unmarshal(localDevRaw, &ld); err != nil {
   154→			return fmt.Errorf("parsing local_dev field: %w", err)
   155→		}
   156→		settings.LocalDev = ld
   157→	}
   158→
   159→	// Override log_level if present and non-empty
   160→	if logLevelRaw, ok := raw["log_level"]; ok {
   161→		var ll string
   162→		if err := json.Unmarshal(logLevelRaw, &ll); err != nil {
   163→			return fmt.Errorf("parsing log_level field: %w", err)
   164→		}
   165→		if ll != "" {
   166→			settings.LogLevel = ll
   167→		}
   168→	}
   169→
   170→	// Merge strategy_options if present
   171→	if optionsRaw, ok := raw["strategy_options"]; ok {
   172→		var opts map[string]interface{}
   173→		if err := json.Unmarshal(optionsRaw, &opts); err != nil {
   174→			return fmt.Errorf("parsing strategy_options field: %w", err)
   175→		}
   176→		if settings.StrategyOptions == nil {
   177→			settings.StrategyOptions = opts
   178→		} else {
   179→			for k, v := range opts {
   180→				settings.StrategyOptions[k] = v
   181→			}
   182→		}
   183→	}
   184→
   185→	// Override agent if present and non-empty
   186→	if agentRaw, ok := raw["agent"]; ok {
   187→		var a string
   188→		if err := json.Unmarshal(agentRaw, &a); err != nil {
   189→			return fmt.Errorf("parsing agent field: %w", err)
   190→		}
   191→		if a != "" {
   192→			settings.Agent = a
   193→		}
   194→	}
   195→
   196→	// Override agent_auto_detect if present
   197→	if autoDetectRaw, ok := raw["agent_auto_detect"]; ok {
   198→		var ad bool
   199→		if err := json.Unmarshal(autoDetectRaw, &ad); err != nil {
   200→			return fmt.Errorf("parsing agent_auto_detect field: %w", err)
   201→		}
   202→		settings.AgentAutoDetect = &ad
   203→	}
   204→
   205→	// Merge agent_options if present
   206→	if agentOptsRaw, ok := raw["agent_options"]; ok {
   207→		var opts map[string]interface{}
   208→		if err := json.Unmarshal(agentOptsRaw, &opts); err != nil {
   209→			return fmt.Errorf("parsing agent_options field: %w", err)
   210→		}
   211→		if settings.AgentOptions == nil {
   212→			settings.AgentOptions = opts
   213→		} else {
   214→			for k, v := range opts {
   215→				settings.AgentOptions[k] = v
   216→			}
   217→		}
   218→	}
   219→
   220→	// Override telemetry if present
