    21→	// PostHogEndpoint is set at build time for production
    22→	PostHogEndpoint = "https://eu.i.posthog.com"
    23→)
    24→
    25→// Client defines the telemetry interface
    26→type Client interface {
    27→	TrackCommand(cmd *cobra.Command, strategy string, agent string, isEntireEnabled bool)
    28→	Close()
    29→}
    30→
    31→// NoOpClient is a no-op implementation for when telemetry is disabled
    32→type NoOpClient struct{}
    33→
    34→func (n *NoOpClient) TrackCommand(_ *cobra.Command, _ string, _ string, _ bool) {}
    35→func (n *NoOpClient) Close()                                                    {}
    36→
    37→// silentLogger suppresses PostHog log output - expected for CLI best-effort telemetry
    38→type silentLogger struct{}
    39→
    40→func (silentLogger) Logf(_ string, _ ...interface{})   {}
    41→func (silentLogger) Debugf(_ string, _ ...interface{}) {}
    42→func (silentLogger) Warnf(_ string, _ ...interface{})  {}
    43→func (silentLogger) Errorf(_ string, _ ...interface{}) {}
    44→
    45→// PostHogClient is the real telemetry client
    46→type PostHogClient struct {
    47→	client     posthog.Client
    48→	machineID  string
    49→	cliVersion string
    50→	mu         sync.RWMutex
    51→}
    52→
    53→// NewClient creates a new telemetry client based on opt-out settings.
    54→// The telemetryEnabled parameter comes from settings; nil means not configured (default to disabled).
    55→//
    56→//nolint:ireturn // Factory function - returns NoOpClient or PostHogClient based on settings
    57→func NewClient(version string, telemetryEnabled *bool) Client {
    58→	// Environment variable takes priority
    59→	if os.Getenv("ENTIRE_TELEMETRY_OPTOUT") != "" {
    60→		return &NoOpClient{}
    61→	}
    62→
    63→	// Check settings preference (nil = not set, default to disabled)
    64→	if telemetryEnabled == nil || !*telemetryEnabled {
    65→		return &NoOpClient{}
    66→	}
    67→
    68→	id, err := machineid.ProtectedID("entire-cli")
    69→	if err != nil {
    70→		return &NoOpClient{}
    71→	}
    72→
    73→	// Use a fast-timeout HTTP transport for telemetry - we don't want to block CLI exit
    74→	transport := &http.Transport{
    75→		DialContext: (&net.Dialer{
    76→			Timeout: 100 * time.Millisecond,
    77→		}).DialContext,
    78→		TLSHandshakeTimeout:   100 * time.Millisecond,
    79→		ResponseHeaderTimeout: 100 * time.Millisecond,
    80→	}
    81→
    82→	client, err := posthog.NewWithConfig(PostHogAPIKey, posthog.Config{
    83→		Endpoint:           PostHogEndpoint,
    84→		ShutdownTimeout:    100 * time.Millisecond, // Don't block CLI exit waiting for telemetry
    85→		BatchUploadTimeout: 200 * time.Millisecond, // Fast timeout - telemetry is best-effort
    86→		Transport:          transport,
    87→		Logger:             silentLogger{}, // Suppress warnings on timeout (expected)
    88→		DisableGeoIP:       posthog.Ptr(true),
    89→		DefaultEventProperties: posthog.NewProperties().
