    55→		slog.String("strategy", g.strategyName),
    56→		slog.Bool("success", err == nil),
    57→	}
    58→	logging.LogDuration(g.ctx, slog.LevelDebug, g.hookName+" hook completed", g.start, append(attrs, extraAttrs...)...)
    59→}
